const webhookData = $('Webhook').first().json;
const originalBody = webhookData.body || {};
const backendResponse = $input.first().json || {};

const isValid = backendResponse.success === true;

if (!isValid) {
  let httpStatus = 401;
  const errObj = (typeof backendResponse.error === 'object' && backendResponse.error !== null) ? backendResponse.error : {};
  const rawStatus = backendResponse.statusCode || backendResponse.status || errObj.status || errObj.statusCode;

  if (rawStatus) {
    httpStatus = parseInt(rawStatus, 10);
  } else if (backendResponse.error) {
    httpStatus = 503;
  }
  if (isNaN(httpStatus) || httpStatus < 400) {
    httpStatus = 401;
  }

  let errorMessage = backendResponse.message;
  if (!errorMessage && errObj.message) {
    try {
      const match = errObj.message.match(/\{.*\}/);
      if (match) {
        const parsed = JSON.parse(match[0]);
        errorMessage = parsed.message;
      }
    } catch (e) {}
    if (!errorMessage) {
      errorMessage = errObj.message;
    }
  }
  if (!errorMessage) {
    errorMessage = httpStatus >= 500 ? "Service temporarily unavailable" : "Webhook verification failed";
  }

  return [{
    json: {
      valid: false,
      httpStatus: httpStatus,
      response: {
        success: false,
        error: httpStatus >= 500 ? "TEMPORARY_ERROR" : (httpStatus === 400 ? "BAD_REQUEST" : "UNAUTHORIZED"),
        message: errorMessage
      }
    }
  }];
}

const eventData = originalBody['event-data'] || originalBody.eventData || {};
const rawEvent = eventData.event || 'unknown';
const rawSeverity = eventData.severity || null;

let eventType = rawEvent;
let status = rawEvent.toUpperCase();

if (rawEvent === 'failed') {
  if (rawSeverity === 'permanent') {
    eventType = 'bounced';
    status = 'BOUNCED';
  } else {
    eventType = 'failed';
    status = 'FAILED_TEMPORARY';
  }
} else if (rawEvent === 'delivered') {
  status = 'DELIVERED';
} else if (rawEvent === 'complained') {
  status = 'SPAM_COMPLAINT';
} else if (rawEvent === 'rejected') {
  status = 'REJECTED';
}

const recipient = eventData.recipient || (eventData.message && eventData.message.recipients ? eventData.message.recipients[0] : null);
const messageHeaders = (eventData.message && eventData.message.headers) || {};
const messageId = messageHeaders['message-id'] || messageHeaders['Message-Id'] || null;

const deliveryStatus = eventData['delivery-status'] || {};
const details = {
  reason: eventData.reason || deliveryStatus.message || deliveryStatus.description || null,
  severity: rawSeverity,
  code: deliveryStatus.code || null,
  description: deliveryStatus.description || null
};

const userVariables = eventData['user-variables'] || {};
const metadata = {
  tenantId: userVariables.tenantId || null,
  registrationId: userVariables.registrationId || null,
  correlationId: userVariables.correlationId || null,
  template: userVariables.template || null
};

const eventId = backendResponse.eventId || eventData.id || `evt_${Date.now()}`;
const eventTimestamp = eventData.timestamp ? new Date(eventData.timestamp * 1000).toISOString() : new Date().toISOString();

const isAlertable = ['BOUNCED', 'FAILED_TEMPORARY', 'SPAM_COMPLAINT', 'REJECTED'].includes(status) || ['bounced', 'failed', 'complained', 'rejected'].includes(eventType);

const alertText = `ACYA Email Service detected an email delivery problem.\n\nEvent:\n${status || eventType}\n\nRecipient:\n${recipient || 'N/A'}\n\nTemplate:\n${metadata.template || 'N/A'}\n\nTenant:\n${metadata.tenantId || 'N/A'}\n\nRegistration:\n${metadata.registrationId || 'N/A'}\n\nCorrelation ID:\n${metadata.correlationId || 'N/A'}\n\nMailgun Message ID:\n${messageId || 'N/A'}\n\nMailgun Event ID:\n${eventId || 'N/A'}\n\nTimestamp:\n${eventTimestamp}\n\nReason:\n${details.reason || 'N/A'}\n\nSeverity:\n${details.severity || 'N/A'}\n\nThis is an operational notification only.`;

return [{
  json: {
    valid: true,
    eventId: eventId,
    eventType: eventType,
    status: status,
    recipient: recipient,
    messageId: messageId,
    timestamp: eventTimestamp,
    details: details,
    metadata: metadata,
    isAlertable: isAlertable,
    alertSubject: `[ACYA Email Alert] Email ${eventType || status}`,
    alertText: alertText,
    response: {
      success: true,
      processed: backendResponse.processed ?? true,
      eventId: eventId,
      eventType: eventType
    }
  }
}];
